'use client';

import { useState } from 'react';
import Link from 'next/link';
import { motion } from 'framer-motion';
import { Search, Clock, Eye, MessageSquare, ArrowRight } from 'lucide-react';
import Card from '@/components/atoms/Card';
import Badge from '@/components/atoms/Badge';

const categories = ['All', 'AI', 'Cloud', 'DevOps', 'Testing', 'Tutorials', 'News'];

const blogs = [
    { id: 1, slug: 'getting-started-with-llms', title: 'Getting Started with Large Language Models in 2026', excerpt: 'A comprehensive guide to understanding and building with LLMs, from GPT to open-source alternatives.', category: 'AI', tags: ['AI', 'LLM', 'Tutorial'], readTime: 8, views: 2450, comments: 23, date: 'Feb 28, 2026', author: 'Alex Chen' },
    { id: 2, slug: 'kubernetes-production-guide', title: 'Kubernetes in Production: Best Practices', excerpt: 'Learn how to run Kubernetes clusters in production with security, monitoring, and scalability in mind.', category: 'DevOps', tags: ['Kubernetes', 'DevOps'], readTime: 12, views: 1890, comments: 18, date: 'Feb 25, 2026', author: 'Marcus Williams' },
    { id: 3, slug: 'aws-vs-azure-vs-gcp-2026', title: 'AWS vs Azure vs GCP: 2026 Comparison', excerpt: 'An in-depth comparison of the top three cloud platforms with pricing, features, and use cases.', category: 'Cloud', tags: ['AWS', 'Azure', 'GCP'], readTime: 15, views: 3200, comments: 45, date: 'Feb 22, 2026', author: 'Sarah Johnson' },
    { id: 4, slug: 'cypress-ai-testing', title: 'AI-Powered Test Automation with Cypress', excerpt: 'How to leverage AI tools to supercharge your Cypress E2E testing workflow.', category: 'Testing', tags: ['Cypress', 'Testing', 'AI'], readTime: 10, views: 1560, comments: 12, date: 'Feb 20, 2026', author: 'Priya Patel' },
    { id: 5, slug: 'terraform-infra-as-code', title: 'Infrastructure as Code with Terraform', excerpt: 'Master Terraform for managing cloud infrastructure across multiple providers.', category: 'DevOps', tags: ['Terraform', 'IaC'], readTime: 11, views: 2100, comments: 31, date: 'Feb 18, 2026', author: 'Marcus Williams' },
    { id: 6, slug: 'neural-network-fundamentals', title: 'Neural Network Fundamentals Explained', excerpt: 'Understanding the building blocks of neural networks from perceptrons to transformers.', category: 'AI', tags: ['AI', 'Neural Networks'], readTime: 14, views: 4200, comments: 56, date: 'Feb 15, 2026', author: 'Alex Chen' },
];

export default function Blog() {
    const [activeCategory, setActiveCategory] = useState('All');
    const [searchQuery, setSearchQuery] = useState('');

    const filteredBlogs = blogs.filter((blog) => {
        const matchCategory = activeCategory === 'All' || blog.category === activeCategory;
        const matchSearch = blog.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            blog.excerpt.toLowerCase().includes(searchQuery.toLowerCase());
        return matchCategory && matchSearch;
    });

    return (
        <div className="py-12 md:py-20">
            <div className="container-custom">
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="text-center mb-10 md:mb-14">
                    <Badge className="mb-4">≡ƒô░ Tech Blog</Badge>
                    <h1 className="text-3xl sm:text-4xl md:text-5xl font-bold mb-4">Latest <span className="neon-text">Insights</span></h1>
                    <p className="text-[var(--text-secondary)] max-w-xl mx-auto">Expert articles on AI, Cloud, DevOps, and Software Testing.</p>
                </motion.div>

                {/* Search + Filters */}
                <div className="flex flex-col md:flex-row gap-4 mb-8 md:mb-10">
                    <div className="relative flex-1">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--text-secondary)]" />
                        <input
                            type="search"
                            placeholder="Search articles..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-12 pr-4 py-3 rounded-xl glass text-[var(--text-primary)] placeholder-[var(--text-secondary)] focus:outline-none focus:border-[var(--neon-cyan)] transition-colors"
                            aria-label="Search articles"
                        />
                    </div>
                    <div className="flex flex-wrap gap-2">
                        {categories.map((cat) => (
                            <button
                                key={cat}
                                onClick={() => setActiveCategory(cat)}
                                className={`px-4 py-2 rounded-xl text-sm font-medium transition-all ${activeCategory === cat
                                        ? 'neon-btn'
                                        : 'glass text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                                    }`}
                            >
                                {cat}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Blog Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
                    {filteredBlogs.map((blog, i) => (
                        <motion.div key={blog.id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Link href={`/blog/${blog.slug}`}>
                                <Card className="h-full flex flex-col group">
                                    <div className="h-40 md:h-48 rounded-xl mb-4 bg-gradient-to-br from-[rgba(0,240,255,0.1)] to-[rgba(168,85,247,0.1)] flex items-center justify-center">
                                        <span className="text-4xl opacity-50">≡ƒô¥</span>
                                    </div>
                                    <div className="flex items-center gap-2 mb-3">
                                        <Badge color={blog.category === 'AI' ? '#00f0ff' : blog.category === 'Cloud' ? '#a855f7' : blog.category === 'DevOps' ? '#10b981' : '#f59e0b'}>
                                            {blog.category}
                                        </Badge>
                                        <span className="text-xs text-[var(--text-secondary)]">{blog.date}</span>
                                    </div>
                                    <h2 className="text-lg font-semibold mb-2 group-hover:text-[var(--neon-cyan)] transition-colors line-clamp-2">{blog.title}</h2>
                                    <p className="text-sm text-[var(--text-secondary)] mb-4 flex-1 line-clamp-2">{blog.excerpt}</p>
                                    <div className="flex items-center justify-between text-xs text-[var(--text-secondary)] pt-3 border-t border-[var(--glass-border)]">
                                        <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {blog.readTime} min</span>
                                        <span className="flex items-center gap-1"><Eye className="w-3 h-3" /> {blog.views}</span>
                                        <span className="flex items-center gap-1"><MessageSquare className="w-3 h-3" /> {blog.comments}</span>
                                    </div>
                                </Card>
                            </Link>
                        </motion.div>
                    ))}
                </div>

                {filteredBlogs.length === 0 && (
                    <div className="text-center py-20">
                        <p className="text-[var(--text-secondary)] text-lg">No articles found matching your search.</p>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { motion } from 'framer-motion';
import { Mail, Phone, MapPin, Send, MessageSquare } from 'lucide-react';
import Badge from '@/components/atoms/Badge';

export default function Contact() {
    const [form, setForm] = useState({ name: '', email: '', subject: '', message: '' });
    const [status, setStatus] = useState<'idle' | 'sending' | 'sent' | 'error'>('idle');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setStatus('sending');
        setTimeout(() => setStatus('sent'), 1500);
    };

    return (
        <div className="py-12 md:py-20">
            <div className="container-custom max-w-5xl">
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="text-center mb-12 md:mb-16">
                    <Badge className="mb-4">≡ƒô¼ Get In Touch</Badge>
                    <h1 className="text-3xl sm:text-4xl md:text-5xl font-bold mb-4">Contact <span className="neon-text">Us</span></h1>
                    <p className="text-[var(--text-secondary)] max-w-xl mx-auto">Have a question or want to collaborate? We&apos;d love to hear from you.</p>
                </motion.div>

                <div className="grid md:grid-cols-5 gap-8 md:gap-12">
                    {/* Contact Info */}
                    <div className="md:col-span-2 space-y-6">
                        <div className="glass-card p-6">
                            <Mail className="w-6 h-6 text-[var(--neon-cyan)] mb-3" />
                            <h3 className="font-semibold mb-1">Email</h3>
                            <a href="mailto:contact@qaawizards.com" className="text-sm text-[var(--text-secondary)] hover:text-[var(--neon-cyan)] transition-colors">contact@qaawizards.com</a>
                        </div>
                        <div className="glass-card p-6">
                            <Phone className="w-6 h-6 text-[var(--neon-cyan)] mb-3" />
                            <h3 className="font-semibold mb-1">Phone</h3>
                            <p className="text-sm text-[var(--text-secondary)]">+1 (555) 000-0000</p>
                        </div>
                        <div className="glass-card p-6">
                            <MapPin className="w-6 h-6 text-[var(--neon-cyan)] mb-3" />
                            <h3 className="font-semibold mb-1">Location</h3>
                            <p className="text-sm text-[var(--text-secondary)]">San Francisco, CA</p>
                        </div>
                    </div>

                    {/* Form */}
                    <div className="md:col-span-3">
                        <form onSubmit={handleSubmit} className="glass-card p-6 md:p-8 space-y-4">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div>
                                    <label htmlFor="contact-name" className="block text-sm font-medium mb-2">Name</label>
                                    <input id="contact-name" type="text" required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })}
                                        className="w-full px-4 py-3 rounded-xl glass text-[var(--text-primary)] placeholder-[var(--text-secondary)] focus:outline-none focus:border-[var(--neon-cyan)]"
                                        placeholder="Your name" />
                                </div>
                                <div>
                                    <label htmlFor="contact-email" className="block text-sm font-medium mb-2">Email</label>
                                    <input id="contact-email" type="email" required value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })}
                                        className="w-full px-4 py-3 rounded-xl glass text-[var(--text-primary)] placeholder-[var(--text-secondary)] focus:outline-none focus:border-[var(--neon-cyan)]"
                                        placeholder="your@email.com" />
                                </div>
                            </div>
                            <div>
                                <label htmlFor="contact-subject" className="block text-sm font-medium mb-2">Subject</label>
                                <input id="contact-subject" type="text" required value={form.subject} onChange={(e) => setForm({ ...form, subject: e.target.value })}
                                    className="w-full px-4 py-3 rounded-xl glass text-[var(--text-primary)] placeholder-[var(--text-secondary)] focus:outline-none focus:border-[var(--neon-cyan)]"
                                    placeholder="How can we help?" />
                            </div>
                            <div>
                                <label htmlFor="contact-message" className="block text-sm font-medium mb-2">Message</label>
                                <textarea id="contact-message" required rows={5} value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })}
                                    className="w-full px-4 py-3 rounded-xl glass text-[var(--text-primary)] placeholder-[var(--text-secondary)] focus:outline-none focus:border-[var(--neon-cyan)] resize-none"
                                    placeholder="Tell us more..." />
                            </div>
                            <button type="submit" disabled={status === 'sending'} className="neon-btn w-full py-3 rounded-xl inline-flex items-center justify-center gap-2 text-base font-semibold">
                                {status === 'sending' ? 'Sending...' : status === 'sent' ? 'Γ£ô Message Sent!' : <><Send className="w-4 h-4" /> Send Message</>}
                            </button>
                        </form>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { motion } from 'framer-motion';
import { Mail, Lock, Eye, EyeOff, Zap } from 'lucide-react';
import Badge from '@/components/atoms/Badge';

export default function Login() {
    const [form, setForm] = useState({ email: '', password: '' });
    const [showPassword, setShowPassword] = useState(false);
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setTimeout(() => setLoading(false), 1500);
    };

    return (
        <div className="min-h-[80vh] flex items-center justify-center py-12 px-4">
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md">
                <div className="text-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-[var(--neon-cyan)] to-[var(--neon-purple)] flex items-center justify-center mx-auto mb-4">
                        <Zap className="w-7 h-7 text-white" />
                    </div>
                    <h1 className="text-2xl md:text-3xl font-bold mb-2">Welcome Back</h1>
                    <p className="text-[var(--text-secondary)] text-sm">Sign in to your QA_AI_WIZARDS account</p>
                </div>

                <form onSubmit={handleSubmit} className="glass-card p-6 md:p-8 space-y-5">
                    <div>
                        <label htmlFor="login-email" className="block text-sm font-medium mb-2">Email</label>
                        <div className="relative">
                            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--text-secondary)]" />
                            <input id="login-email" type="email" required value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })}
                                className="w-full pl-11 pr-4 py-3 rounded-xl glass text-[var(--text-primary)] placeholder-[var(--text-secondary)] focus:outline-none focus:border-[var(--neon-cyan)]"
                                placeholder="your@email.com" autoComplete="email" />
                        </div>
                    </div>
                    <div>
                        <label htmlFor="login-password" className="block text-sm font-medium mb-2">Password</label>
                        <div className="relative">
                            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--text-secondary)]" />
                            <input id="login-password" type={showPassword ? 'text' : 'password'} required value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })}
                                className="w-full pl-11 pr-11 py-3 rounded-xl glass text-[var(--text-primary)] placeholder-[var(--text-secondary)] focus:outline-none focus:border-[var(--neon-cyan)]"
                                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" autoComplete="current-password" />
                            <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2" aria-label={showPassword ? 'Hide password' : 'Show password'}>
                                {showPassword ? <EyeOff className="w-4 h-4 text-[var(--text-secondary)]" /> : <Eye className="w-4 h-4 text-[var(--text-secondary)]" />}
                            </button>
                        </div>
                    </div>
                    <div className="flex items-center justify-between text-sm">
                        <label className="flex items-center gap-2 cursor-pointer">
                            <input type="checkbox" className="rounded border-[var(--glass-border)]" />
                            <span className="text-[var(--text-secondary)]">Remember me</span>
                        </label>
                        <a href="#" className="text-[var(--neon-cyan)] hover:underline">Forgot password?</a>
                    </div>
                    <button type="submit" disabled={loading} className="neon-btn w-full py-3 rounded-xl font-semibold">
                        {loading ? 'Signing in...' : 'Sign In'}
                    </button>
                </form>

                <p className="text-center text-sm text-[var(--text-secondary)] mt-6">
                    Don&apos;t have an account? <Link href="/register" className="text-[var(--neon-cyan)] hover:underline font-medium">Sign Up</Link>
                </p>
            </motion.div>
        </div>
    );
}

'use client';

import dynamic from 'next/dynamic';
import { motion } from 'framer-motion';
import Link from 'next/link';
import { ArrowRight, Brain, Cloud, Shield, TestTube, Code, Users, BookOpen, Rocket } from 'lucide-react';
import Card from '@/components/atoms/Card';
import Badge from '@/components/atoms/Badge';

const Hero3D = dynamic(() => import('@/components/organisms/Hero3D'), { ssr: false });

const techAreas = [
  { icon: Brain, title: 'AI & Machine Learning', desc: 'Master neural networks, LLMs, computer vision, and AI automation frameworks.', color: '#00f0ff', href: '/roadmaps' },
  { icon: Cloud, title: 'Cloud Computing', desc: 'AWS, Azure, GCP ΓÇö Infrastructure, serverless, and cloud-native architectures.', color: '#a855f7', href: '/roadmaps' },
  { icon: Code, title: 'DevOps Engineering', desc: 'CI/CD, Kubernetes, Docker, Terraform, and modern infrastructure automation.', color: '#10b981', href: '/roadmaps' },
  { icon: TestTube, title: 'Software Testing', desc: 'E2E testing, performance testing, security testing, and QA automation.', color: '#f59e0b', href: '/roadmaps' },
];

const stats = [
  { value: '50+', label: 'Expert Roadmaps' },
  { value: '200+', label: 'Learning Resources' },
  { value: '10K+', label: 'Community Members' },
  { value: '95%', label: 'Success Rate' },
];

const features = [
  { icon: Shield, title: 'Industry-Proven Curriculum', desc: 'Built by senior engineers and tech leads from top companies.' },
  { icon: Users, title: 'Active Community', desc: 'Connect with thousands of professionals and mentors worldwide.' },
  { icon: BookOpen, title: 'Hands-On Learning', desc: 'Real-world projects, labs, and certifications to build your portfolio.' },
  { icon: Rocket, title: 'Career Acceleration', desc: 'From junior to senior ΓÇö structured paths for every career stage.' },
];

const container = {
  hidden: { opacity: 0 },
  show: { opacity: 1, transition: { staggerChildren: 0.1 } },
};

const item = {
  hidden: { opacity: 0, y: 20 },
  show: { opacity: 1, y: 0 },
};

export default function Home() {
  return (
    <>
      {/* Hero Section */}
      <section className="relative min-h-[90vh] lg:min-h-screen flex items-center overflow-hidden" aria-label="Hero">
        <Hero3D />
        <div className="container-custom relative z-10 py-20 md:py-32">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
            className="max-w-3xl"
          >
            <Badge className="mb-4 md:mb-6">≡ƒÜÇ Next-Gen Tech Education Platform</Badge>
            <h1 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl xl:text-7xl font-bold leading-tight mb-4 md:mb-6">
              Master the Future of{' '}
              <span className="neon-text">Technology</span>
            </h1>
            <p className="text-base sm:text-lg md:text-xl text-[var(--text-secondary)] max-w-2xl mb-6 md:mb-8 leading-relaxed">
              QA_AI_WIZARDS is your gateway to mastering AI, Cloud Computing, DevOps, and Software Testing
              with expert-curated roadmaps and a thriving global community.
            </p>
            <div className="flex flex-col sm:flex-row gap-3 sm:gap-4">
              <Link href="/roadmaps" className="neon-btn text-center px-6 py-3 md:px-8 md:py-4 rounded-xl text-base md:text-lg font-semibold inline-flex items-center justify-center gap-2 group">
                Explore Roadmaps <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
              </Link>
              <Link href="/community" className="glass neon-border text-center px-6 py-3 md:px-8 md:py-4 rounded-xl text-base md:text-lg font-medium text-[var(--text-primary)] hover:bg-[rgba(0,240,255,0.1)] transition-all">
                Join Community
              </Link>
            </div>
          </motion.div>
        </div>
        {/* Gradient overlay at bottom */}
        <div className="absolute bottom-0 left-0 right-0 h-32 bg-gradient-to-t from-[var(--dark-bg)] to-transparent z-10" />
      </section>

      {/* Stats */}
      <section className="py-12 md:py-16 border-y border-[var(--glass-border)]" aria-label="Statistics">
        <div className="container-custom">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6 md:gap-8">
            {stats.map((stat, i) => (
              <motion.div
                key={stat.label}
                initial={{ opacity: 0, scale: 0.8 }}
                whileInView={{ opacity: 1, scale: 1 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.1 }}
                className="text-center"
              >
                <p className="text-2xl sm:text-3xl md:text-4xl font-bold neon-text">{stat.value}</p>
                <p className="text-xs sm:text-sm text-[var(--text-secondary)] mt-1">{stat.label}</p>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Tech Areas */}
      <section className="py-16 md:py-24" aria-label="Technology areas">
        <div className="container-custom">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-center mb-12 md:mb-16"
          >
            <Badge className="mb-4">≡ƒÄ» Our Expertise</Badge>
            <h2 className="text-2xl sm:text-3xl md:text-4xl font-bold mb-4">
              Master the <span className="neon-text">Tech Ecosystem</span>
            </h2>
            <p className="text-[var(--text-secondary)] max-w-2xl mx-auto text-sm md:text-base">
              Comprehensive learning paths designed by industry experts to take you from beginner to expert.
            </p>
          </motion.div>

          <motion.div
            variants={container}
            initial="hidden"
            whileInView="show"
            viewport={{ once: true }}
            className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6"
          >
            {techAreas.map((area) => (
              <motion.div key={area.title} variants={item}>
                <Link href={area.href}>
                  <Card className="h-full group">
                    <div
                      className="w-12 h-12 md:w-14 md:h-14 rounded-xl flex items-center justify-center mb-4 transition-all group-hover:scale-110"
                      style={{ background: `${area.color}15`, border: `1px solid ${area.color}30` }}
                    >
                      <area.icon className="w-6 h-6 md:w-7 md:h-7" style={{ color: area.color }} />
                    </div>
                    <h3 className="text-base md:text-lg font-semibold mb-2">{area.title}</h3>
                    <p className="text-sm text-[var(--text-secondary)]">{area.desc}</p>
                  </Card>
                </Link>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </section>

      {/* Features */}
      <section className="py-16 md:py-24 border-t border-[var(--glass-border)]" aria-label="Features">
        <div className="container-custom">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-center mb-12 md:mb-16"
          >
            <Badge color="#a855f7" className="mb-4">Γ£¿ Why QA_AI_WIZARDS</Badge>
            <h2 className="text-2xl sm:text-3xl md:text-4xl font-bold mb-4">
              Everything You Need to <span className="neon-text">Succeed</span>
            </h2>
          </motion.div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
            {features.map((feat, i) => (
              <Card key={feat.title} className="text-center group">
                <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-[rgba(0,240,255,0.1)] to-[rgba(168,85,247,0.1)] flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                  <feat.icon className="w-7 h-7 text-[var(--neon-cyan)]" />
                </div>
                <h3 className="font-semibold mb-2">{feat.title}</h3>
                <p className="text-sm text-[var(--text-secondary)]">{feat.desc}</p>
              </Card>
            ))}
          </div>
        </div>
      </section>

      {/* CTA */}
      <section className="py-16 md:py-24" aria-label="Call to action">
        <div className="container-custom">
